<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ClientIdentity\Domain\Gateway;

use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ClientIdentity;

class ClientIdentityCursor
{
    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
    ) {
    }
    public function next(ClientIdentity $clientIdentity, ?int $size): ClientIdentityCursor
    {
        $next = clone $this;
        $next->sinceUid = $clientIdentity->uid();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
}
